<script>
import { defineAsyncComponent } from 'vue';
import GalleryMark from './GalleryMark.vue';
import GalleryProjectLink from './GalleryProjectLink.vue';
import AiViewTerm from '../ui/AiViewTerm.vue';
import ExhibitionTicket from './ExhibitionTicket.vue';
import sample from '../../data/projectTicketSample.json';
import { galleryStudyFeatures } from '../../data/galleryDesignStudies';
import { lockBodyScroll } from '../../utils/bodyScrollLock';
import { initDialogBackdrop } from '../../utils/dialogBackdrop';
import { animateGalleryDialog } from '../../utils/galleryDialogMotion';
import { preloadExhibitionStudies } from '../../utils/galleryDesignMedia';

const loadDesignExhibition = () => import('./MuseumDesignExhibition.vue');

export default {
  components:{GalleryMark,GalleryProjectLink,AiViewTerm,ExhibitionTicket,
    GalleryDesignPlate:defineAsyncComponent(()=>import('../ui/GalleryDesignPlate.vue')),
    MuseumDesignExhibition:defineAsyncComponent(loadDesignExhibition),
    ViewPresentationJourneyDemo:defineAsyncComponent(()=>import('../ui/ViewPresentationJourneyDemo.vue'))},
  props:{chapter:{type:String,default:'gallery'},dark:Boolean,open:{type:Boolean,default:true},insideGallery:{type:Boolean,default:true}},
  emits:['close','project'],
  data(){return {active:this.chapter,closing:false,viewportStyle:{},sample,features:['hall-across','building','orientation','light-dark'].map(id=>galleryStudyFeatures.find(f=>f.id===id)),chapters:[{id:'gallery',title:'Gallery'},{id:'view',title:'View'},{id:'exhibition',title:'Exhibition'}]};},
  watch:{open(value){if(value)this.show();else this.hide();}},
  mounted(){
    this.syncViewport();this._viewport=window.visualViewport;
    this._viewport?.addEventListener('resize',this.syncViewport);this._viewport?.addEventListener('scroll',this.syncViewport);window.addEventListener('resize',this.syncViewport);
    this._stopBackdrop=initDialogBackdrop(this.$refs.dialog,()=>this.leave());
    if(this.open)this.show();
  },
  beforeUnmount(){
    this._destroyed=true;this._motion?.cancel();this._stopBackdrop?.();
    this._viewport?.removeEventListener('resize',this.syncViewport);this._viewport?.removeEventListener('scroll',this.syncViewport);window.removeEventListener('resize',this.syncViewport);
    this.$refs.dialog?.close();this._releaseScroll?.();if(this._trigger?.isConnected)this._trigger.focus({preventScroll:true});
  },
  methods:{
    openProject(event){this.$emit('project',event);},
    show(){
      preloadExhibitionStudies();loadDesignExhibition().catch(()=>{});
      this.active=this.chapter;this.closing=false;this._trigger=document.activeElement;
      this._releaseScroll?.();this._releaseScroll=lockBodyScroll();
      this.$refs.dialog.showModal();this._motion=animateGalleryDialog(this.$refs.dialog,true,this._motion);
      this.$refs.close.focus({preventScroll:true});
    },
    hide(){
      this._motion?.cancel();this.$refs.dialog.close();this._releaseScroll?.();this._releaseScroll=null;
      this.closing=false;this.active='gallery';
      if(this._trigger?.isConnected)this._trigger.focus({preventScroll:true});this._trigger=null;
    },
    syncViewport(){const v=window.visualViewport,w=v?.width||innerWidth,h=v?.height||innerHeight;this.viewportStyle={'--dialog-centre-x':`${(v?.offsetLeft||0)+w/2}px`,'--dialog-centre-y':`${(v?.offsetTop||0)+h/2}px`,'--dialog-height':`${h}px`,'--dialog-width':`${w}px`};},
    select(id){if(this.active===id)return;this.active=id;if(this.$refs.body)this.$refs.body.scrollTop=0;},
    tabKey(event,index){const keys={ArrowRight:(index+1)%3,ArrowLeft:(index+2)%3,Home:0,End:2};if(!(event.key in keys))return;event.preventDefault();const next=this.chapters[keys[event.key]].id;this.select(next);this.$nextTick(()=>this.$refs.dialog.querySelector(`#design-tab-${next}`).focus());},
    async leave(){if(this.closing)return;this.closing=true;this._motion=animateGalleryDialog(this.$refs.dialog,false,this._motion);await this._motion?.finished.catch(()=>{});if(!this._destroyed)this.$emit('close');},
  },
};
</script>
